Otras variables: {{other}}', '{"type":"object","properties":{"cost":{"type":"string","title":"Costo del producto","description":"Incluye sourcing + handling"},"price":{"type":"string","title":"Precio de venta"},"shipping":{"type":"string","title":"Costo de envío"},"adSpend":{"type":"string","title":"Gasto en ads (por unidad o total)"},"other":{"type":"string","title":"Otros costos (opcional)","description":"Comisiones, plataforma, taxes, etc."}},"required":["cost","price"]}', 'structured', 2000, 0.3, false, 51, ARRAY['roi','margen','unit-economics']),

